command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="500bfeb1bba994fe658a40d036c8d391ae6a8db0"
$candidate="4fb9055a3a3bf322be817acf36e2adbd02d4f672"
$branch="work/search-scale-20261006"
$temp=Join-Path $env:RUNNER_TEMP ("fly-search-scale-"+$env:GITHUB_RUN_ID)
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "search scale fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before search scale acceptance"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "search scale candidate moved"}
if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp 2>$null;Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue}
& git worktree add --detach $temp $candidate
if($LASTEXITCODE -ne 0){throw "search scale worktree creation failed"}
try{
  Set-Location -LiteralPath $temp
  & git diff --check ($main+"..."+$candidate)
  if($LASTEXITCODE -ne 0){throw "search scale diff check failed"}
  & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
  if($LASTEXITCODE -ne 0){throw "search scale FAST failed"}
  & cmd /c tests\winui\m19\build.cmd Release
  if($LASTEXITCODE -ne 0){throw "M19 Release fixture build failed"}
  $env:FLY_M19_CONFIG="Release"
  & python -X utf8 tests\winui\m19\test_native.py
  if($LASTEXITCODE -ne 0){throw "M19 Release native scale acceptance failed"}
  Remove-Item Env:\FLY_M19_CONFIG -ErrorAction SilentlyContinue
  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "canonical Release build failed"}
  & python -X utf8 tools\winui\run_checks.py gui --area search --configuration Release
  if($LASTEXITCODE -ne 0){throw "search GUI regression failed"}
  Write-Host "SEARCH_SCALE_FAST=PASS"
  Write-Host "SEARCH_SCALE_M19_NATIVE=PASS"
  Write-Host "SEARCH_SCALE_RELEASE=PASS"
  Write-Host "SEARCH_SCALE_GUI=PASS"
} finally {
  Set-Location -LiteralPath $repo
  Remove-Item Env:\FLY_M19_CONFIG -ErrorAction SilentlyContinue
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
